/* global document */
// Reconstruct the current report while preserving the original PDF unchanged.
import { readFile, writeFile } from "node:fs/promises";
import { chromium } from "@playwright/test";
import { pathToFileURL, fileURLToPath } from "node:url";
const root = new URL("../../", import.meta.url);
const read = async (path) => JSON.parse(await readFile(new URL(path, root), "utf8"));
const evidence = await read("6. Project Testing/report-evidence.json");
const captures = evidence.captures;
const e = await read("8-Project-Demonstration/public/data/evaluation.json");
const model = await read("8-Project-Demonstration/public/data/model.json");
const esc = (s) => String(s).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
const p = (s) => `<p>${s}</p>`;
const sub = (title, text) => `<h2>${title}</h2>${p(text)}`;
const list = (items) => `<ul>${items.map((s) => `<li>${s}</li>`).join("")}</ul>`;
const table = (heads, rows) => `<table><thead><tr>${heads.map((s) => `<th>${s}</th>`).join("")}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((s) => `<td>${s}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
const code = (s) => `<pre>${esc(s)}</pre>`;
let figureNumber = 0;
const fig = (file, caption, extra = "") => `<figure class="${extra}"><img src="../6. Project Testing/${file}" alt="${caption}"/><figcaption>Figure ${++figureNumber}. ${caption}</figcaption></figure>`;
const pages = [];
const add = (title, body) => pages.push({ title, body });

add("Abstract and revision statement", p("The HDI Prediction &amp; Analytics System presents published human-development observations alongside a reproducible machine-learning approximation of the Human Development Index. The current application is a cyan React and TypeScript website, branded HDI Intelligence, with local numerical inference and an optional Vercel function for Groq explanations. It preserves the internship's subject while replacing the former Flask interface and its deployment assumptions.")
  + p(`The pinned UNDP Human Development Report 2025 data supplies ${e.rows.toLocaleString("en-US")} complete country-year records for ${e.countries} countries over 1990-2023. Country-separated validation selects ${e.name.toLowerCase()}; held-out MAE is ${e.test.mae.toFixed(6)}, RMSE is ${e.test.rmse.toFixed(6)} and R² is ${e.test.r2.toFixed(6)}. These values come from the existing evaluation artifact, not a new training run. The formula reference performs better, as expected for an index defined by the same supplied components.`)
  + sub("Scope of this revision", "Phase 4 repairs chart rendering, connects the year selector to historical plots, adds explicit missing-observation states and verifies the current numerical and personal-key workflows. The original 38-page PDF was read in full, including its ER diagram, code images, evaluation graphics and former application screenshots. This reconstruction retains its academic progression, project-flow epics, team record and conclusion while replacing obsolete active-system descriptions.")
  + sub("Scientific boundary", "Reconstructing current HDI from contemporaneous components is not forecasting future HDI. Hypothetical changes to input indicators do not prove the effects of government spending or other interventions. AI explanations are optional prose, not the numerical estimator.")
  + sub("Preservation", "The original Project Documentation.pdf is preserved unchanged inside the local Historical project backup.zip in folder 7. No editable Word source was found. This revised report has an editable HTML companion and a reproducible generator in phase 8. No faculty details, team contributions, institutional approval or deployment completion have been invented."));

add("Original academic team record", p("The following names and roles are transcribed from page 1 of the original report. They describe the original team record, not newly assigned modernization work or independently verified contributions.")
  + table(["Name", "Original role", "Original responsibility summary"], [
    ["Manda Vijaya Sri", "Backend Developer", "Flask backend, prediction APIs, authentication, database integration and reporting."],
    ["Madireddy Meena Mahanth Harinadh", "Machine Learning Engineer", "Dataset preparation, EDA, regression comparison, saved models and model documentation."],
    ["Ramcharanteja Batchu", "Project Manager &amp; Integration", "Planning, repository coordination, integration, deployment and presentation."],
    ["Dileep Kumar Arivilli", "Frontend Developer", "Original HTML, CSS, Bootstrap and JavaScript interface and Flask integration."],
    ["Phaneendra Annavarapu", "Data Visualization &amp; Testing Engineer", "Original charts, benchmarking, explorer, testing and documentation."],
  ]) + sub("Academic context", "The repository records an AI &amp; ML internship through SmartBridge Educational Services Pvt. Ltd. in collaboration with APSCHE, described by the owner as 120 hours over two months. This report does not certify attendance, historical milestone dates or institutional assessment.")
  + sub("Project identity", "The current title is HDI Prediction &amp; Analytics System. The original title, A Comprehensive Measure of Well-Being (HDI Predict), is retained here for traceability. The public website uses HDI Intelligence and a footer credit to Madireddy Meena Mahanth Harinadh. Historical planning and original source remain in their documented folders."));

add("Introduction and project description", p("Economic output alone cannot describe the opportunities people have to live long, educated and materially secure lives. HDI combines health, education and standard-of-living dimensions into a bounded index. A score closer to one indicates higher achievement in those dimensions, but does not capture every inequality, environmental cost or personal experience.")
  + p("This project provides a practical teaching interface for these ideas. A visitor can inspect published country records, compare historical trends, change four indicators, calculate an ML estimate and compare it with a direct formula. The separation between observations, model estimates and hypothetical scenarios is visible in the interface and preserved in exports.")
  + sub("The four active inputs", "Life expectancy at birth represents health. Expected years of schooling and mean years of schooling represent education for different cohorts. GNI per capita, expressed in constant 2021 purchasing-power-parity dollars, represents living standards. Population, public expenditure and region are not numerical features of the current model.")
  + table(["HDI category", "Threshold used in the application"], [["Low", "Below 0.550"], ["Medium", "0.550 to below 0.700"], ["High", "0.700 to below 0.800"], ["Very high", "0.800 and above"]])
  + p("Country and region labels support exploration; they do not change the estimator. The optional explanation service receives validated indicators and server-recomputed results. It is instructed to discuss limitations and avoid invented ranks, confidence intervals and causal policy effects."));

add("Problem statement, objectives and scope", p("The practical problem is making a published multi-dimensional development measure easy to explore and interpret without disguising an index reconstruction experiment as independent forecasting. Static spreadsheets make comparisons cumbersome, while an attractive interface can still mislead if its data mappings, charts or claims are wrong.")
  + list(["Expose real country-year records and clearly label their source and observation year.", "Provide repeatable local estimates using the committed trained model and unchanged preprocessing.", "Show the direct formula beside the model result so approximation error is understandable.", "Support hypothetical scenarios and transparent baseline comparisons without causal claims.", "Make charts, inputs, exports, mobile navigation and optional AI controls functional.", "Keep personal provider credentials request-scoped and out of persistent application storage.", "Maintain one coherent academic record across the eight numbered project folders."])
  + sub("Users and interpretation", "Students and reviewers can examine the full workflow from data to model evidence. Researchers can compare published observations and inspect assumptions. The system does not provide validated forecasts, investment guidance or evidence that a particular policy will change a country's development category.")
  + sub("Out of scope", "The active application has no accounts, authentication database, stored prediction history, policy recommendation engine, PDF export button, live UNDP synchronization or trained uncertainty model. JSON exports are implemented. The academic PDF is a repository deliverable, not an application-generated prediction report."));

add("Existing system and proposed system", p("The original report describes Flask, Bootstrap, SQLite/MySQL, pickle loading, authentication, prediction history and Render deployment. Its screenshots and ER diagram are historical evidence of that earlier design. They must not be used to claim that these services exist in the current public website.")
  + table(["Concern", "Earlier report", "Current application"], [["Frontend", "Flask/Jinja and Bootstrap", "React, TypeScript, Vite and centralized cyan CSS"], ["Inference", "Python model on the server", "Exported estimator in shared JavaScript"], ["Data", "Earlier experimental panel", "Pinned official UNDP HDR 2025 snapshot"], ["Identity/storage", "Accounts and database", "No account or database; local transient state"], ["AI", "Recommendation narrative", "Optional Groq explanations with personal keys"], ["Deployment", "Render/WSGI description", "Vercel static frontend plus Node function"]])
  + sub("Why the separation matters", "The browser can calculate HDI without a provider key or a Python service. The optional API repeats numerical calculations before requesting prose. This reduces coupling and prevents a language model from becoming the source of numerical predictions. Deployment still needs to be performed and verified separately by the project owner.")
  + sub("Preserved evidence", "The historical backup preserves legacy source, obsolete datasets/models, the original report and dated verification records. Earlier evaluation and screenshot collections retain their historical labels. Phase 4 does not retrain the model or replace scientific artifacts to improve reported metrics."));

const diagram = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 860 460" role="img" aria-label="Current system architecture"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#087d96"/></marker></defs><style>text{font:18px 'Times New Roman';fill:#083344}.box{fill:#ecfeff;stroke:#087d96;stroke-width:2}.flow{fill:none;stroke:#087d96;stroke-width:2;marker-end:url(#arrow)}</style><rect class="box" x="20" y="25" width="235" height="85" rx="8"/><text x="38" y="58">Pinned data + model JSON</text><text x="38" y="85">Versioned static artifacts</text><rect class="box" x="320" y="25" width="245" height="85" rx="8"/><text x="340" y="58">React website / Vite</text><text x="340" y="85">Country and scenario state</text><path class="flow" d="M255 67H315"/><rect class="box" x="620" y="25" width="220" height="85" rx="8"/><text x="638" y="58">Browser inference</text><text x="638" y="85">Model + direct formula</text><path class="flow" d="M565 67H615"/><rect class="box" x="320" y="170" width="245" height="90" rx="8"/><text x="338" y="203">Personal key in tab memory</text><text x="338" y="232">Explicit Generate action</text><path class="flow" d="M442 110V165"/><rect class="box" x="320" y="320" width="245" height="95" rx="8"/><text x="338" y="350">Same-origin Vercel API</text><text x="338" y="375">Validate + recompute results</text><text x="338" y="400">Request-scoped credential</text><path class="flow" d="M442 260V315"/><text x="458" y="291">HTTPS</text><rect class="box" x="620" y="320" width="220" height="95" rx="8"/><text x="638" y="355">Groq API</text><text x="638" y="385">Optional explanation</text><path class="flow" d="M565 360H615"/><path class="flow" d="M620 395H575"/><rect x="20" y="170" width="235" height="245" rx="8" fill="#f8fafb" stroke="#a1b6bc"/><text x="37" y="202">Core numerical tools:</text><text x="37" y="234">No API key required</text><text x="37" y="266">No account or database</text><text x="37" y="298">No live Python service</text><text x="37" y="348">Host receives the AI key</text><text x="37" y="378">only for an AI request.</text></svg>`;
add("System architecture and data flow", p("The active application has two execution boundaries: a static browser application and an optional same-origin Node function. Offline Python training produced the committed artifacts; it is not part of ordinary website requests.") + `<figure>${diagram}<figcaption>Figure ${++figureNumber}. Current React, inference and optional Groq architecture.</figcaption></figure>`
  + p("The browser loads countries.json, model.json and evaluation.json. The historical explorer lazily loads explorer.json. Shared inference code validates four inputs, computes the trained estimate and calculates dimension indices. The API imports the same model artifact and inference module to reconstruct evidence before calling Groq.")
  + p("The hosting server necessarily receives a personal key when an explanation is requested. It is not invisible to the operator. No key is placed in a URL, application log, database or persistent browser store. The response contains sanitized prose or a bounded error, never a normal credential echo."));

add("Data entities and state boundaries", p("The original ER diagram is replaced by a description of the entities that actually exist. There are no active User, Recommendation or Report database tables. The current data model consists of JSON artifacts and transient state.")
  + table(["Entity", "Fields or contents", "Lifetime"], [["Country", "ISO3, name, source region, 2023 indicators, published HDI and history", "Committed public data"], ["Country-year", "ISO3, year, four indicators and observed HDI", "Committed complete-case panel"], ["Model", "Feature order, coefficients, intercept, medians and observed ranges", "Committed trained artifact"], ["Evaluation", "Split groups, comparisons, held-out metrics, samples and limitations", "Committed experiment evidence"], ["Draft / baseline / scenario", "Four validated inputs; baseline changes only on calculation", "React memory"], ["Personal AI credential", "Masked UI entry, current status and request revision", "Active tab memory"], ["Export", "Selected records or committed prediction inputs and outputs", "User-requested JSON download"]])
  + sub("Consistency rules", "Country selection loads a published preset. Editing fields does not silently change the committed predictor result: a stale-result notice requests another calculation. A newly calculated baseline resets the scenario. Historical presets carry their source year into the predictor. Removing or replacing a key cancels pending browser work and clears the old explanation; a request already sent upstream cannot be recalled.")
  + sub("Theme preference", "Light/dark preference uses localStorage separately from credentials. No opt-in credential persistence has been added. Refreshing the page clears the personal key and transient input state."));

add("Prerequisites and technology stack", p("Ordinary use requires a modern browser and the committed static data. Local development uses Node 24.x and the repository's lockfile. Python is needed for the preserved offline research workflow, not for entering indicators or viewing existing results.")
  + table(["Layer", "Implementation", "Purpose"], [["UI", "React 19 and TypeScript", "Accessible controls and state-driven pages"], ["Build", "Vite 7; Tailwind CSS 4 integration", "Development server and static output"], ["Visualization", "Recharts 3", "Historical areas, scenario bars, sensitivity and scatter plot"], ["Styling", "Cyan tokens and responsive CSS", "Shared light/dark identity and reduced motion"], ["Inference", "shared/inference.mjs", "Validation, model, formula, categories and sensitivity"], ["Optional API", "Node function on Vercel", "Origin validation and Groq requests"], ["Research", "Python, Pandas, NumPy, scikit-learn", "Existing dataset preparation and regression experiment"], ["Verification", "TypeScript, ESLint, Node tests, Playwright, axe", "Static, numerical, API and browser checks"]])
  + sub("Skills and environment", "Developers should understand typed component state, HTTP boundaries, accessible HTML, descriptive statistics and held-out evaluation. Git is useful for source control, but this delivered workspace is a downloaded archive without .git. No new repository history or past team activities were fabricated.")
  + sub("Hardware", "No GPU is required for the exported linear estimator. The project has not established measured minimum hardware requirements or public concurrency capacity. The earlier report's hardware recommendations should not be interpreted as benchmarks of the current application."));

add("Project flow: Epics 1 and 2", sub("Epic 1 - Environment setup and installation", "The purpose remains reproducibility. Work from the active application in folder 8, install locked dependencies, and start the local frontend/API adapter. A fresh installation uses the following commands from the repository root.")
  + code('cd "8-Project-Demonstration"\nnpm ci\nnpm run dev')
  + p("Open http://127.0.0.1:5173. The local Node adapter listens on 127.0.0.1:3001. On Windows, if PowerShell blocks npm.ps1, use npm.cmd ci and npm.cmd run dev without changing machine-wide execution policy. Restart the development server after endpoint or environment edits.")
  + sub("Epic 2 - Libraries and application initialization", "The React entry point mounts App inside StrictMode. App loads the three initial JSON assets and provides retry feedback if loading fails. Explorer loads its larger historical panel only when opened. Numeric inference is imported from the shared module; no browser pickle loading or server Python process is required.")
  + p("The developer configuration may read ignored .env values for the local API. Public personal-key use does not need an owner key in that file. API credentials must never be prefixed with VITE_, because such variables are intended for client-visible configuration.")
  + sub("Expected outcome", "A working local website and optional same-origin API route, with the environment documented independently from the offline research environment. The legacy Flask requirements remain with the archived application and are not the installation path for the active website."));

add("Project flow: Epic 3 - Dataset collection", p("The current research snapshot is the official UNDP HDR 2025 complete time series. Its source URL and SHA-256 are recorded in evaluation.json. A pinned copy supports reproducibility even when the external source is later revised. Phase 4 uses the existing files rather than downloading a different release or regenerating the model.")
  + table(["Artifact fact", "Recorded value"], [["Source release", e.dataset], ["Complete country-year records", e.rows], ["Countries", e.countries], ["Latest-year countries", e.latestCountries], ["Observation years", "1990-2023"], ["Excluded incomplete rows", e.droppedRows], ["Raw source SHA-256", `<span class="hash">${e.sha256}</span>`]])
  + sub("Feature and target understanding", "The target is published HDI. The four inputs are life expectancy, expected schooling, mean schooling and GNI per capita. ISO3 identifies countries consistently; country names are display labels. Regions use the source grouping, including Other / not assigned where the source does not assign a region.")
  + sub("Coverage limitations", "A complete-case dataset is not a claim that every country has every year available. Missing historical observations remain gaps and missing four-indicator records cannot supply a predictor preset. Country-year records are not statistically independent; related economies and repeated observations matter when interpreting scores.")
  + p("The source link appears beside the repaired trend. Observed values are kept distinct from formula-derived indices and model-generated estimates. Exported table records correspond to the selected year, region, text search and development category."));

add("Project flow: Epic 4 - Data preprocessing", p("The active training script reshapes source columns into a country-year panel, excludes regional aggregates and drops rows missing any model input or HDI. It checks duplicate country-year keys and the valid HDI interval. The recorded count of 622 excluded rows reflects that existing experiment, not a new Phase 4 cleaning run.")
  + sub("Numerical transformation", "GNI is transformed with the natural logarithm before model evaluation. The other three inputs retain their original units. The feature order is fixed in model.json. Training and inference do not introduce a StandardScaler, median imputation or categorical encoding for this selected four-feature model.")
  + code("x = [life_expectancy, expected_schooling, mean_schooling, ln(gni_per_capita)]\ny_hat = clip(intercept + sum(coefficients[i] * x[i]), 0, 1)")
  + sub("Validation and extrapolation", "The user interface rejects empty, non-finite and out-of-bound inputs. Life expectancy must be 20-95; expected schooling 0-25; mean schooling 0-20; and GNI 100-200,000. These accepted UI bounds are not claims that the training data covers every combination. The model's observed ranges separately trigger an extrapolation warning.")
  + sub("Corrections to the original report", "The former generic examples described mean/median filling, IQR outlier treatment and feature scaling as completed preprocessing. Those steps do not describe the current pinned experiment and are therefore not repeated as active-system facts. Country presets are rounded to two decimals for entry; that display choice is separate from the original source precision.")
  + p("Expected and mean years of schooling describe different cohorts and are validated independently. An unusual combination can remain mathematically accepted while being substantively implausible; the interface does not turn that combination into a causal policy simulation."));

add("Project flow: Epics 5 and 6", sub("Epic 5 - Exploratory data analysis", "Exploration should reveal the source data rather than conceal missingness. The current website provides historical HDI trends, two-country comparisons, dimension summaries and a searchable indicator table. The older report's distribution and correlation images belonged to the earlier experiment; they are preserved in that original PDF rather than relabeled as current UNDP findings.")
  + p("The temporal chart includes every calendar year within the selected range. Values must be finite and within [0, 1]; absent observations are null. Series do not connect across missing years. A one-year selection uses visible point markers. Selecting the same country twice shows a single trend rather than duplicate legend entries. The exact-value table remains an alternative to the chart.")
  + sub("Epic 6 - Country-separated splitting", "The current experiment uses GroupShuffleSplit by ISO3. An outer split with seed 42 reserves test countries; an inner split with seed 43 separates training and validation countries. Thus the same country's repeated annual rows cannot occur in both training and a held-out country group.")
  + table(["Partition", "Rows", "Purpose"], [["Training", e.split.train, "Fit comparison models"], ["Validation", e.split.validation, "Select lowest MAE"], ["Test", e.split.test, "Evaluate selected refitted model once"]])
  + p("The winner is refitted on training plus validation countries before final evaluation. Grouping reduces repeated-country leakage, but does not remove dependence between economies or years. The separate 2019-2023 temporal diagnostic uses contemporaneous indicators and is still not a forecast of unknown future conditions."));

add("Project flow: Epic 7 - Model development", p("The modernized experiment compares four regression families: linear regression, decision tree, random forest and Extra Trees. The validation MAE determines the selected algorithm. Additional algorithms listed in the original report are not presented as newly evaluated models unless the current artifact contains their results.")
  + table(["Model", "Validation MAE", "Validation RMSE", "Validation R²"], [...e.comparison].sort((a,b)=>a.mae-b.mae).map((m)=>[m.name,m.mae.toFixed(6),m.rmse.toFixed(6),m.r2.toFixed(6)]))
  + sub("Selection and complexity", "Linear regression has the lowest recorded validation MAE and a compact coefficient-based representation. The implementation uses its fitted intercept and coefficients, with a logarithmic income feature and bounded outputs. Choosing a more complicated algorithm merely because it appears more advanced would not follow the recorded selection rule.")
  + sub("Original synthetic experiment", "The earlier panel included invented country peers and formula-derived targets with added noise. The preserved modernization audit compares random-row and country-family splits on a four-feature Extra Trees comparator. It does not claim exact reproduction of the original eight-feature pickle. The archive remains useful for explaining why the data source and evaluation procedure were revised.")
  + p("No model was trained, selected again or tuned during this functional repair. All numerical model comparisons in this report are read from the committed evaluation artifact. The website's output is calculated from the model, not hardcoded to match screenshots."));

add("Project flow: Epic 8 - Evaluation", p("MAE measures average absolute error in HDI points. RMSE gives greater weight to large deviations. R² expresses explained variation relative to the test-target mean; it is not a percentage classification accuracy. The model and direct formula are evaluated against published HDI on the same held-out rows.")
  + table(["Evaluation", "MAE", "RMSE", "R²"], [["Held-out countries",e.test.mae.toFixed(6),e.test.rmse.toFixed(6),e.test.r2.toFixed(6)],["Direct formula, same rows",e.formula.mae.toFixed(6),e.formula.rmse.toFixed(6),e.formula.r2.toFixed(6)],["Temporal diagnostic",e.temporal.mae.toFixed(6),e.temporal.rmse.toFixed(6),e.temporal.r2.toFixed(6)]] )
  + sub("Interpretation", "Strong reconstruction scores are expected because HDI is defined by the supplied components. The formula reference's lower error is not an implementation failure; it is an essential baseline that prevents overstatement of the learned approximation. Source rounding and revisions can explain small differences from the published index.")
  + sub("What the charts show", "The methodology page presents validation comparisons, a scatter plot of held-out published versus predicted HDI, sample counts and feature reliance. The scatter artifact includes every fifth test row. Permutation importance reports the increase in test MAE after shuffling a feature over eight repeats. Correlated inputs constrain its interpretation.")
  + sub("What is not established", "These scores do not validate forecasts, causal recommendations, calibrated uncertainty intervals or performance on every out-of-range input. The result should be interpreted as educational index reconstruction, supported by the direct formula and recorded limitations."));

add("Formula reference and local sensitivity", p("The formula view makes the relationship between the inputs and the target explicit. Each dimension index is capped to [0, 1]. The schooling terms use different reference maxima and their arithmetic mean forms the education index; the three dimension indices are then combined with a geometric mean.")
  + code("Health = cap((life_expectancy - 20) / 65)\nEducation = (cap(expected_schooling / 18) + cap(mean_schooling / 15)) / 2\nIncome = cap(ln(gni_per_capita / 100) / ln(750))\nHDI_formula = cube_root(Health * Education * Income)")
  + p("This is the calculation implemented in shared/inference.mjs and used as the reference throughout the application. It should be preferred over an approximate model when the relevant components are already known. The training artifact's validation and test errors remain separate from the direct formula's numerical error.")
  + sub("Sensitivity analysis", "The predictor replaces one current input with its training median while holding the others fixed. The displayed effect is the original prediction minus that replacement prediction. Positive bars mean the current value raises the estimate relative to the median replacement. These effects are neither SHAP values nor additive contributions.")
  + sub("Scenario comparison", "The scenario starts from the last committed baseline. Editing a scenario runs the same estimator again; the displayed delta is the updated estimate minus the baseline estimate. Reset copies the baseline inputs back. Invalid values suppress the comparison chart instead of plotting fabricated zero-valued scenario observations."));

add("Project flow: Epics 9 and 10", sub("Epic 9 - Model saving and reproducible inference", `The selected model is exported as JSON with schema version ${model.schemaVersion}, feature order, fitted coefficients, intercept, medians and observed ranges. The same JavaScript module is imported by the browser and API. Existing reference data contains ${e.parityCases} Python prediction cases, allowing JavaScript parity to be checked without retraining.`)
  + p("The original pickle artifacts are preserved inside the local historical backup for reproduction. They are not served to the browser or deserialized as part of visitor interaction. No credentials belong in a public model or evaluation file.")
  + sub("Epic 10 - Public web application development", "The Flask-development epic is retained as a project-flow stage but its current implementation is React. App owns the committed baseline and scenario state. Navbar exposes five public routes. Shared controls render validated inputs, categories, score scales and dimension bars. Page modules keep exploration, prediction, scenarios and methodology distinct.")
  + table(["Component", "Responsibility"], [["Trend", "Published history, year range, gaps, tooltips and exact-value table"],["Predictor", "Draft inputs, committed estimate, formula and export"],["Scenarios", "Baseline/update comparison and reset"],["AIContext / AISettings", "Transient personal credential and status"],["Insights / Explanation", "Explicit request and safe prose/table rendering"]])
  + p("The cyan brand, custom SVG mark, responsive top navigation, dark theme and reduced-motion support are preserved. ResponsiveContainer controls chart sizing; external percentage max-width constraints must not override its measured drawing width."));

add("Project flow: Epic 11 - State and privacy", p("The original database-integration epic is intentionally revised: there is no active user database or stored prediction history. The visitor's selections and inputs live in React state, while data and model artifacts are static. Downloads occur only on request.")
  + sub("Bring Your Own Key", "AI Settings provides masked entry, show/hide, use, change and remove controls. Saving marks a key as configured, not verified. Only a successful explanation request changes status to connected. Refresh clears the key. Removing or changing it aborts pending browser responses and clears the old explanation, without claiming to recall work already sent upstream.")
  + sub("Server protections", "POST /api/insights validates method, content type, exact origin, key format, four numeric inputs and a nonblank question of at most 500 characters. The request body is limited to 4 KiB. An instance-local IP bucket allows six requests per minute, with bounded storage. The function recomputes numerical evidence, sets a 15-second provider timeout and bounds returned text.")
  + sub("Error handling", "Credential rejection, quota/rate limits, timeouts and provider unavailability produce distinct safe responses. Provider error bodies are not forwarded. Credential-shaped text is redacted from normal JSON responses. No fallback to an owner's account occurs after a personal-key failure.")
  + sub("Owner configuration", "Optional owner-key access is disabled by default. Enabling it requires ALLOW_OWNER_AI=true, a server-only GROQ_API_KEY and a strong matching AI_ACCESS_TOKEN for every owner request, including local development. The public UI has no owner-code field. The default Groq model is openai/gpt-oss-20b and remains configurable with GROQ_MODEL."));

add("Project flow: Epic 12 - Verification", p("Phase 4 verification addresses the reported failure and the current personal-key contract. Earlier Phase 1/2 records remain dated historical evidence. Phase 3 deliberately ran no tests; that fact is preserved rather than retroactively changing its status.")
  + table(["Check", "Recorded Phase 4 result"], evidence.checks.map((c) => [esc(c.name), esc(c.result)]))
  + p("Browser coverage includes Cyprus/China, India/United States and Norway/Afghanistan through multiple years; single-year points; South Sudan missing-data behavior; nonzero SVG drawing widths; desktop/mobile and light/dark plots; table filters and exact exports; historical presets; invalid-input blocking; predictor calculation; scenario deltas and reset; menu, theme, accordion and modal interactions.")
  + sub("AI verification boundary", "API unit tests use injected provider responses. Browser AI tests intercept the route with explicitly labeled test fixtures to exercise formatting, invalid credentials, rate limits and key replacement. Those fixtures are not real Groq explanations and are not included as successful AI screenshots. No live provider success or Vercel deployment is claimed in this phase.")
  + sub("Evidence", "Folder 6 keeps consolidated report-evidence.json and the eight report images. Detailed dated logs and earlier captures are preserved in the local historical backup in folder 7. Current cleanup checks are recorded separately in folder 6. Screenshot records identify their actual page state. Passing the checks does not prove behavior in every browser, operating system or public hosting environment."));

add("Project flow: Epic 13 - Deployment", p("Vercel configuration is preserved for the current static frontend and optional Node function. Deploy from folder 8, not the repository root. The owner remains responsible for deployment; no Git push or Vercel publication was performed as part of this revision.")
  + table(["Setting", "Value"], [["Root Directory", "8-Project-Demonstration"],["Install Command", "npm ci"],["Build Command", "npm run build"],["Output Directory", "dist"],["Function", "api/insights.mjs"],["Production APP_ORIGIN", "Exact HTTPS site origin, without trailing slash"],["Owner fallback", "Disabled unless explicitly opted in and token-protected"]])
  + p("The public frontend has no embedded provider secret. Each visitor supplies a personal key for an explicit AI operation. The hosting function sees that key while making the Groq request, so the interface advises visitors to trust the site operator. Browser code refuses to send a key from a non-HTTPS site except local loopback development.")
  + sub("Operational considerations", "The deployment's selected Groq model must be available to the visitor's account. Request limits and account quotas can prevent explanations while numerical functions remain available. The process-local throttle resets on cold starts and is not a durable global quota. Stronger public abuse protection requires hosting or distributed controls.")
  + sub("Static frontend behavior", "Hash routes support refresh on a static host. Core calculations run locally after their artifacts load. Historical explorer data is lazy-loaded; offline behavior before that download is not guaranteed. The project is not packaged as an offline-first service-worker application."));

add("Application walkthrough: Home", p("Home introduces the index and its three dimensions. The custom three-node logo and top navigation establish a public website identity. Published-country data, source-backed dataset totals and a historical trend replace administrative counters or invented marketing statistics.")
  + fig("home.png", "Current homepage with the HDI Intelligence logo, navigation and a real country summary.")
  + p("Predict HDI loads the selected country's indicators into the predictor. Explore Global Data opens the explorer. The country selector beneath the introduction changes the published summary and historical curve. Light/dark styling uses shared cyan tokens; animations respect reduced-motion preferences.")
  + p("The dataset totals come from the actual country and evaluation artifacts: 193 countries, 5,940 complete records and 1990-2023 coverage. These statements describe the pinned release and do not imply complete observations for every country-year combination."));

add("Application walkthrough: Explore Data", p("The explorer combines region, country, observation-year and comparison controls with published records. Selecting a year limits the historical trend through that year and updates both country summaries and the selected country's indicator card. Country labels are mapped by ISO3 identifiers.")
  + fig("explore.png", "Explore Data with Cyprus and China selected and the repaired historical visualization.")
  + p("The table is filtered independently by its visible year, region, search and development-category controls. Export filtered data downloads exactly those table records as JSON. Use these indicators transfers an available complete observation into the predictor with its source year. Missing records have no preset action.")
  + p("The comparison selector may choose a country outside the selected region, allowing cross-region comparisons. The region filter controls the primary-country list and the table. This distinction is deliberate and remains visible in the separate labels."));

add("Historical HDI visualization repair", p("The reported Cyprus/China chart had valid country data, transformed coordinates, series paths, legend names and colors. The actual drawing SVG nevertheless had zero width. A shared CSS rule applied max-width:100% to .recharts-wrapper, whose Recharts measurement parent was zero-width with visible overflow. The rule overrode Recharts' measured pixel width.")
  + fig("trend-detail.png", "Actual published Cyprus/China trend after restoring the measured SVG width.", "trend-figure")
  + table(["Diagnostic", "Before repair", "After removing the constraint"], [["Outer chart width", "Approximately 691 px", "Approximately 691 px"],["Drawing SVG width", "0 px", "691 px"],["Historical records", "34 per country", "Same unchanged records"]])
  + p("The repair removes the conflicting constraint and lets ResponsiveContainer use its measured dimensions. It does not manufacture data or paint decorative lines. A regression check measures the SVG drawing viewport, rather than merely checking that a path exists in the DOM. The same sizing repair restores scenario, sensitivity and methodology charts.")
  + p("The history component now includes missing calendar years explicitly, prevents connecting across absent observations, shows point markers for short ranges and supplies a visible empty state. Its source link and exact-value table provide context and an accessible alternative."));

add("Application walkthrough: HDI Predictor", p("The predictor groups health, schooling and income controls. A country preset is rounded to two decimals for editing. Blank, nonnumeric or out-of-bound entries prevent calculation. A dirty-input notice makes clear when the displayed result still belongs to the previously committed baseline.")
  + fig("predictor.png", "HDI Predictor using genuine model inference and the direct formula reference.")
  + p(`The captured result is ${esc(captures.prediction.score)}. Its exact inputs and numeric export are recorded in the screenshot manifest. The numerical result is produced by the committed estimator, not by Groq or the report generator.`)
  + p("Dimension bars show calculated health, education and income indices. The category follows the defined thresholds. The formula comparison uses the same committed inputs. An expandable sensitivity view provides one-feature median replacements, and Export result saves the inputs, model estimate and formula reference.")
  + p("Reset changes the editable inputs back to the current preset without submitting a new calculation. Explore a scenario carries the committed baseline into the scenario page. Explain this result opens the optional AI panel and does not alter the numeric result."));

add("Application walkthrough: Scenarios", p("Scenario analysis compares a committed baseline with modified indicators. It uses the same estimator for both sides. Invalid inputs hide the scenario chart and replace the numerical delta with a correction prompt. Reset copies the baseline back into the editable scenario.")
  + fig("scenarios.png", "Scenario comparison with actual baseline, edited inputs and calculated differences.")
  + p(`The screenshot records a displayed change of ${esc(captures.scenario.delta)} HDI points. Its input state is saved with the capture. This is a model comparison for a hypothetical indicator combination, not evidence that a policy would cause that change.`)
  + p("The dimension chart distinguishes baseline and scenario values with separate colors and a legend. Exact inputs and dimension differences are available in the table below. Editing the baseline in the predictor and recalculating resets the scenario consistently.")
  + p("The income transformation is logarithmic, so equally sized monetary changes need not have equal model effects. Even when a scenario remains within numeric bounds, correlated inputs and unrealistic combinations can limit interpretation. The interface keeps that limitation alongside the results."));

add("Application walkthrough: Methodology", p("Methodology makes the data source, selection rule and evaluation limits visible. It shows held-out metrics, comparison-model validation errors, row partitions, a published-versus-predicted scatter plot and feature-reliance summaries. The direct formula is explicitly identified as the appropriate reference when the components are known.")
  + fig("methodology.png", "Methodology page with existing evaluation metrics and a visible held-out scatter plot.")
  + p("The downloadable evaluation artifact includes machine-readable evidence and limitations. A perfect diagonal in the scatter plot is a visual reference, not a fitted uncertainty band. Points are sampled from the committed held-out residual records; no new evaluation samples were generated for this report.")
  + p("Expandable technical sections preserve the synthetic-data audit and its interpretation. Country grouping, complete-case selection, data revisions and same-year temporal diagnostics are discussed so that a high reconstruction R² is not mistaken for independent predictive ability."));

add("Application walkthrough: Personal AI Settings", p("The navbar key icon opens a native dialog with keyboard focus containment and Escape dismissal. The key input is masked by default and can be shown explicitly. The saved state means configured for the current tab; it does not imply that Groq has verified the credential.")
  + fig("ai-settings.png", "AI Settings with no credential entered or exposed.", "settings-figure")
  + p("A visitor can change or remove the key at any time. The application sends it only with a requested explanation through the site's backend. Invalid credentials and usage limits leave predictions available. The dialog links to the official Groq console and explains that the host receives the key during processing.")
  + p("No live AI-output screenshot is included: this phase verified provider-dependent success/error presentation through explicit test fixtures, without presenting mocked prose as a real provider response. The original Phase 2 live-provider evidence remains historical and is not relabeled as a new request."));

add("Responsive behavior and accessibility", p("The application retains the cyan identity on small screens and in dark mode. The top navigation becomes a dismissible dropdown, never a persistent sidebar. Inputs remain usable, wide data tables scroll within their cards, and plots receive measured nonzero dimensions.")
  + fig("explore-mobile.png", "Actual mobile historical comparison with responsive chart sizing.", "mobile-figure")
  + p("The current checks cover 390-pixel mobile and desktop chart viewports in both themes, with additional route layout checks at tablet width. Keyboard navigation, skip link, modal dismissal, theme persistence and automated accessibility checks are recorded in phase 6. This is scoped evidence, not a claim of universal accessibility certification.")
  + p("Reduced-motion users receive static results without entrance or chart animation. Exact-value tables provide alternatives to visual trends. Published data, model estimates and scenario results retain distinct labels. No artificial loading delay or additional animation library was introduced for the repair."));

add("Repository organization and preservation", table(["Numbered folder", "Current role and Phase 4 treatment"], [["1. Brainstorming &amp; Ideation", "Preserve original ideas; clarify current noncausal scope."],["2. Requirement Analysis", "Current exploration, prediction, BYOK and responsive requirements."],["3. Project Design Phase", "Actual React, browser inference and serverless diagrams."],["4. Project Planning Phase", "Preserve original timeline; record later repair separately."],["5. Project Development Phase", "Document chart root cause, mapping and current implementation."],["6. Project Testing", "Preserve previous evidence; add measured Phase 4 checks and captures."],["7. Project Documentation", "Original PDF backup, revised report, editable source and technical notes."],["8-Project-Demonstration", "Single active app, tests, report/capture helpers and setup guides."]])
  + p("Final cleanup keeps folders 1-7 flat. Folder 6 retains eight report images and consolidated evidence; folder 7 retains this report, editable HTML and the model card. Historical records, the original academic PDF, old test collections, obsolete Flask source and unused model files are preserved in one verified local Historical project backup.zip. The ZIP is ignored by Git and should be kept separately before publishing.")
  + p("The active React application keeps its required technical directories in folder 8. Official source data, the processed test panel, the synthetic input still used by the training audit, current model artifacts and lockfile are retained. Generated builds, test output and caches can be recreated. No root docs or tools directories are needed. No commit, push or deployment was made."));

add("Limitations, future scope and conclusion", sub("Limitations", "HDI compresses multiple dimensions into an average. It omits distributional inequality and many environmental or institutional conditions. The current estimator reconstructs a formula-defined index; complete-case filtering, source revisions, country dependence and extrapolation constrain its interpretation. Local sensitivity is not causal attribution and the application has no calibrated confidence intervals.")
  + p("AI can produce incorrect prose, depends on account access and may be rate limited. The process-local throttle is not a distributed usage guarantee. The site operator receives a key during requested AI processing. Live Groq success and actual Vercel deployment are not newly verified in this phase. Browser checks cover the recorded engine and viewports, not every device.")
  + sub("Future scope", "A forecasting study would require lagged information, predeclared forward validation and meaningful temporal baselines. Additional dimensions should have explicit sources and justified methods. Durable public throttling, wider assistive-technology evaluation, data-release version selection and explicit export formats can be considered separately without turning an educational comparison into unsupported policy guidance.")
  + sub("Conclusion", "The project connects a reproducible regression experiment with an understandable public interface. The chart defect demonstrates why valid data and DOM paths are insufficient evidence of a visible visualization. Restoring measured SVG dimensions, preserving missing observations, testing actual interactions and rebuilding the academic report align the implementation with its claims.")
  + p("The revised website retains its original cyan branding and genuine model calculations. Current screenshots document real application states; historical evidence remains identifiable. The appropriate conclusion is that the recorded checks support the implemented workflows, while the scientific and deployment limitations remain explicit."));

